function limitador(n) {
  let activos = 0
  const cola = []
  const siguiente = () => {
    if (activos >= n || !cola.length) return
    activos++
    const t = cola.shift()
    Promise.resolve().then(t.fn).then(t.res, t.rej).then(() => { activos--; siguiente() }, () => { activos--; siguiente() })
  }
  return (fn) => new Promise((res, rej) => { cola.push({ fn, res, rej }); siguiente() })
}
