const autores = {}
const trabajos = MODULOS.map((m) => {
  autores[m.id] = (async () => {
    if (m.depende) {
      await Promise.all(m.depende.map((d) => autores[d]))
      log(`${m.id}: dependencias listas (${m.depende.join(', ')}), entra en cola`)
    }
    const informe = await opus(() => agent(PROMPT_AUTOR(m), { label: `autor ${m.id}`, phase: 'Autores', model: 'opus', effort: 'max', agentType: 'general-purpose' }))
    log(`${m.id} escrito${informe ? '' : ' (sin informe)'}`)
    return informe
  })()
  return autores[m.id].then(async (informe) => {
    const revision = await sonnet(() => agent(PROMPT_REVISOR(m, informe), { label: `revisor ${m.id}`, phase: 'Revisión', model: 'sonnet', effort: 'xhigh', agentType: 'general-purpose' }))
    log(`${m.id} revisado`)
    return { id: m.id, informe, revision }
  })
})

const resultados = await Promise.all(trabajos)
return resultados
